from pathlib import Path
from audio_revision import P
out=P/'production/local/final-reviewed'
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>플로 맵 쇼츠 — 최종 검수</title><style>body{margin:20px;background:#171b19;color:#fff;font:16px 'Malgun Gothic',sans-serif}button{font:inherit;margin:5px;padding:8px}video{display:block;width:375px;max-width:100%;background:black}#stats{position:fixed;left:420px;top:20px;background:#171b19;padding:14px}</style><div id="stats"><h2>플로 맵 · 51초</h2><button onclick="v.play()">처음부터 재생</button><button onclick="v.pause()">일시정지</button><button onclick="v.currentTime=0;v.play()">처음으로</button><button onclick="v.style.width='375px'">모바일 375px</button><button onclick="v.style.width='810px'">큰 화면</button><p id="state">준비 중</p><p>최종 사용자 검수 전 · 비공개 업로드 전</p></div><video id="v" controls preload="auto" src="captioned.mp4"></video><script>const v=document.getElementById('v');v.addEventListener('timeupdate',()=>document.getElementById('state').textContent=`${v.currentTime.toFixed(2)} / ${v.duration.toFixed(2)}초 · ${v.paused?'일시정지':'재생 중'} · ${v.videoWidth}×${v.videoHeight}`);</script></html>'''
(out/'playback.html').write_text(html,encoding='utf8')
